# read in data
wave_2_dfs &lt;- readRDS(here("_data", "_intermediary_data", "wave_2_dfs.RDS"))

df &lt;- bind_rows(
  wave_2_dfs[['wave_2_lyrics']] |&gt; 
    select(item_ID, participant_ID, value, rating), 
  wave_2_dfs[['wave_2_speeches']] |&gt; 
    select(item_ID, participant_ID, value, rating), 
  .id = "text") |&gt;

  mutate(text = case_when(
    text == "1" ~ "lyrics", 
    text == "2" ~ "speeches"))


lyrics_df &lt;- readRDS(here("_data", "_primary_data", "lyrics_df.RDS"))




Code
lyrics_rank_df &lt;- df |&gt;
  filter(text == "lyrics") |&gt;
  filter(!is.na(rating)) |&gt;
  group_by(item_ID, participant_ID) |&gt;
  filter(n() &gt; 1) |&gt;
  mutate(rank = dense_rank(-rating)) |&gt;
  arrange(rank, .by_group = TRUE) |&gt;
  summarise(
    ranking = list(as.character(value)),
    .groups = "drop") |&gt;
  left_join(
    lyrics_df |&gt; 
      mutate(item_ID = as.character(item_ID)) |&gt;
      select(item_ID, artist_topic_bin_labels), 
      by = "item_ID")




Code
rra_lyrics &lt;- bind_rows(

  # ranking from the top
  lyrics_rank_df |&gt; 
    group_by(item_ID) |&gt;
    group_modify(~ {

      if (nrow(.x) &lt; 2) {return(tibble())}

      rra &lt;- aggregateRanks(.x$ranking,method = "RRA", exact = T)

      rra |&gt;
        rename(value = Name) |&gt;
        mutate(direction = "top")}) |&gt;
    ungroup(),

  # ranking from the bottom
  lyrics_rank_df |&gt;
    group_by(item_ID) |&gt;
    group_modify(~ {

      if (nrow(.x) &lt; 2) {return(tibble())}

      rra &lt;- aggregateRanks(
        lapply(.x$ranking, rev),
        method = "RRA")

      rra |&gt;
        rename(value = Name) |&gt;
        mutate(direction = "bottom")}) |&gt;
    ungroup()) |&gt;

  mutate(agree = ifelse(Score &lt; .05, 1, 0)) |&gt;

  left_join(
    lyrics_df |&gt; 
      mutate(item_ID = as.character(item_ID)) |&gt;
      select(item_ID, artist_topic_bin_labels), 
    by = "item_ID")




Code
magma_col &lt;- viridis(10, option = "magma")[6]

lyrics_plot_df &lt;- rra_lyrics |&gt;
  group_by(item_ID, artist_topic_bin_labels) |&gt;
  summarise(agreement = sum(agree), .groups = "drop") |&gt;
  count(agreement) |&gt;
  mutate(prop = n / sum(n))

p1 &lt;- ggplot(lyrics_plot_df, aes(x = agreement, y = n)) +
  geom_col(color = "black", fill = magma_col, alpha = .7) +
  geom_text(
    aes(label = scales::percent(prop, accuracy = .1)),
    vjust = -0.4,
    size = 3) +
  scale_x_continuous(limits = c(-.5, 7.5), breaks = 0:7) +
  xlab("Number of Identified Values per Song") +
  ylab("Number of songs") +
  theme_classic()

