run_rra_by_group &lt;- function(df) {

  df &lt;- df |&gt;
    # merge ethnicity and spectrum into a single variable
    mutate(group = paste(Ethnicity, spectrum, sep = " · "))

  bind_rows(
    # top
    df |&gt;
      group_by(group) |&gt;
      group_modify(~ {
        if (nrow(.x) &lt; 2) return(tibble())

        rra &lt;- aggregateRanks(.x$ranking, method = "RRA", exact = FALSE)
        rra |&gt;
          rename(value = Name) |&gt;
          mutate(direction = "top")}) |&gt;
          ungroup(),

    # bottom
    df |&gt;
      group_by(group) |&gt;
      group_modify(~ {

        if (nrow(.x) &lt; 2) return(tibble())

        rra &lt;- aggregateRanks(lapply(.x$ranking, rev), 
                              method = "RRA",exact = FALSE)
        rra |&gt;
          rename(value = Name) |&gt;
          mutate(direction = "bottom")}) |&gt;
        ungroup()
)}




