    pivot_wider(
      names_from  = direction,
      values_from = c(Score, agree),
      names_sep   = "_")  |&gt;

    filter(Score_top &lt;= .05 | Score_bottom &lt;= .05) |&gt;

    mutate(
      salience = case_when(
        agree_top ==   1 ~   1 - Score_top,
        agree_bottom ==1 ~ -(1 - Score_bottom),
        TRUE             ~   0))

  # plot
  viridis_col &lt;- viridis(10, option = "D")


  df |&gt;
    mutate(value = factor(value, levels = value_order)) |&gt;

    mutate(
      salience_dir = case_when(
        salience &gt; 0 ~ "Top",
        salience &lt; 0 ~ "Bottom",
        TRUE         ~ NA_character_)) |&gt;

    ggplot(aes(x = group, y = value, fill = salience_dir)) +
      geom_tile(color = "white", linewidth = 0.3) +
      scale_fill_manual(
        values = c(
          "Bottom"  = viridis_col[3],
          "Top"     = viridis_col[6]),
        breaks = c("Top", "Bottom"),
        name = "Rank Placement") +

      labs(x = "Rater Characteristic", y = "Value", 
           title = "Salient Values by Rater Characteristic") +
      theme_classic() +
      theme(
        axis.text.x = element_text(angle = 45, hjust = 1), 
        plot.title = element_text(hjust = 0.5),
        legend.position = "right") +  coord_flip()

})




